input.content:
// Consent and window gate for the assistant's own follow-up messages.
// State lives in memory only; it is lost on process restart.

// Opt-out and opt-in keywords follow the usual carrier/CTIA text-program convention.
const OPT_OUT_KEYWORDS = new Set(['STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT']);
const OPT_IN_KEYWORDS = new Set(['START', 'UNSTOP', 'YES']);

// WhatsApp customer-service window: free text is allowed only within 24h of the customer's last message.
const WINDOW_MS = 24 * 60 * 60 * 1000;

// userId -> { lastInboundMs: number | null, optedOut: boolean }
const customers = new Map();

// Reduce a raw message to a keyword candidate: trim whitespace, punctuation, symbols and
// invisible format characters from both ends, then compare case-insensitively.
// Internal words are kept, so "stop by the store" is not a keyword.
function keywordOf(text) {
  if (typeof text !== 'string') return null;
  return text
    .normalize('NFKC')
    .replace(/^[\s\p{P}\p{S}\p{Cf}]+|[\s\p{P}\p{S}\p{Cf}]+$/gu, '')
    .toUpperCase();
}

function isValidDate(value) {
  return value instanceof Date && !Number.isNaN(value.getTime());
}

export function onInbound(userId, text, at) {
  if (!isValidDate(at)) {
    throw new TypeError('onInbound: at must be a valid Date');
  }

  let customer = customers.get(userId);
  if (!customer) {
    customer = { lastInboundMs: null, optedOut: false };
    customers.set(userId, customer);
  }

  const ms = at.getTime();
  customer.lastInboundMs = customer.lastInboundMs === null ? ms : Math.max(customer.lastInboundMs, ms);

  const keyword = keywordOf(text);
  if (OPT_OUT_KEYWORDS.has(keyword)) {
    customer.optedOut = true;
  } else if (OPT_IN_KEYWORDS.has(keyword)) {
    customer.optedOut = false;
  }
}

function blocked(rule) {
  return { allowed: false, rule };
}

export function check(userId, type, now) {
  // Fail closed on anything we do not understand.
  if (type !== 'freeform' && type !== 'template') return blocked('invalid_type');
  if (!isValidDate(now)) return blocked('invalid_time');

  const customer = customers.get(userId);

  if (customer?.optedOut) return blocked('opted_out');
  if (!customer || customer.lastInboundMs === null) return blocked('no_prior_inbound');
  if (type === 'freeform' && now.getTime() - customer.lastInboundMs >= WINDOW_MS) {
    return blocked('freeform_window_closed');
  }

  return { allowed: true, rule: null };
}

input.command:
D=$(mktemp -d) && cat > "$D/check.mjs" <<'EOF'
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g5-2/bot.mjs';

const H = 3600_000;
const t0 = new Date('2026-10-23T10:00:00Z');
const at = (h) => new Date(t0.getTime() + h * H);

// Never wrote to us: nothing allowed.
assert.deepEqual(check('new', 'freeform', at(0)), { allowed: false, rule: 'no_prior_inbound' });
assert.deepEqual(check('new', 'template', at(0)), { allowed: false, rule: 'no_prior_inbound' });

// Inbound opens freeform window; 23h59m later still open, 24h later closed.
onInbound('a', 'hi', t0);
assert.deepEqual(check('a', 'freeform', at(23.99)), { allowed: true, rule: null });
assert.deepEqual(check('a', 'freeform', at(24)), { allowed: false, rule: 'freeform_window_closed' });
// Template still allowed after window closes.
assert.deepEqual(check('a', 'template', at(48)), { allowed: true, rule: null });

// Stop variants, case/punctuation/whitespace insensitive, all block everything.
for (const word of ['STOP', ' stop ', 'Stop.', '*STOP*!', 'stop!!!', '​STOP​', 'ｓｔｏｐ', 'UNSUBSCRIBE', 'cancel', 'End', 'quit', 'STOPALL']) {
  onInbound('b', 'hello', t0);
  onInbound('b', word, at(1));
  assert.deepEqual(check('b', 'template', at(2)), { allowed: false, rule: 'opted_out' }, word);
  assert.deepEqual(check('b', 'freeform', at(2)), { allowed: false, rule: 'opted_out' }, word);
  // Restore for next iteration
  onInbound('b', 'START', at(3));
}

// Ordinary sentences containing keywords are not opt-outs.
for (const text of ['Can you stop by the store?', 'please stop texting me', 'no stop', 'stop, thanks', 'the end', 'cancel my order please']) {
  onInbound('c', text, t0);
  assert.deepEqual(check('c', 'freeform', at(0.5)), { allowed: true, rule: null }, text);
}

// Opt-in restores sending; non-keyword messages do not.
onInbound('d', 'hi', t0);
onInbound('d', 'STOP', at(0.1));
onInbound('d', 'hello again', at(0.2));
assert.equal(check('d', 'template', at(0.3)).rule, 'opted_out');
onInbound('d', ' Start! ', at(0.4));
assert.deepEqual(check('d', 'template', at(0.5)), { allowed: true, rule: null });
onInbound('e', 'hi', t0);
onInbound('e', 'stop', at(0.1));
onInbound('e', 'UNSTOP', at(0.2));
assert.deepEqual(check('e', 'freeform', at(0.3)), { allowed: true, rule: null });
onInbound('f', 'stop', t0);
onInbound('f', 'YES', at(0.1));
assert.deepEqual(check('f', 'template', at(0.2)), { allowed: true, rule: null });

// A new inbound refreshes the window.
onInbound('g', 'hi', t0);
onInbound('g', 'hi again', at(30));
assert.deepEqual(check('g', 'freeform', at(40)), { allowed: true, rule: null });

// Out-of-order timestamps do not shrink the window.
onInbound('h', 'hi', at(30));
onInbound('h', 'older', at(0));
assert.deepEqual(check('h', 'freeform', at(31)), { allowed: true, rule: null });

// Fail closed on bad input.
assert.equal(check('a', 'sms', at(1)).rule, 'invalid_type');
assert.equal(check('a', 'freeform', new Date('x')).rule, 'invalid_time');
assert.throws(() => onInbound('a', 'hi', '2026-10-23'), TypeError);

console.log('all checks passed');
EOF
node "$D/check.mjs" && echo "exit $?"; rm -rf "$D"
